export function t(key, lang, vars) {
  const row = T[key];
  let s = (row && (row[lang] || row.en)) || key;
  if (vars) for (const k in vars) s = s.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
  return s;
}

export function normLang(l) {
  return LANGS.includes(l) ? l : "en";
}
